    long long range = R - L + 1;
    const long long mod = 998244353;
    long long result;
    if (total % 2 == 1) {
        result = fastExponentiation(range, total, mod);
    } else if (range % 2 == 0) {
        long long temp = fastExponentiation(range, total, mod);
        result = (temp * (mod + 1) / 2) % mod;
    } else {
        long long temp = fastExponentiation(range, total, mod);
        result = (((temp + 1) % mod) * (mod + 1) / 2) % mod;
    }
    cout << result << "\n";
